// Direct embedded Base64 PDF to guarantee 100% reliable instant download without CDN/server routing issues
export const RESUME_PDF_BASE64 = "";

export function downloadResumePdf(filename = "Rohit_Prajapat_Resume.pdf") {
  try {
    const byteCharacters = atob(RESUME_PDF_BASE64);
    const byteNumbers = new Array(byteCharacters.length);
    for (let i = 0; i < byteCharacters.length; i++) {
      byteNumbers[i] = byteCharacters.charCodeAt(i);
    }
    const byteArray = new Uint8Array(byteNumbers);
    const blob = new Blob([byteArray], { type: "application/pdf" });
    
    const blobUrl = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = blobUrl;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    
    setTimeout(() => {
      document.body.removeChild(link);
      URL.revokeObjectURL(blobUrl);
    }, 1000);
  } catch (err) {
    console.error("Blob download fallback:", err);
    window.open("https://raw.githubusercontent.com/Prajapatrohit21/myportfolio/main/public/Rohit_Prajapat_Resume.pdf", "_blank");
  }
}
